def sequences(grid):
    seqs=[]
    for i,row in enumerate(grid):
        j=0
        while j<len(row):
            if row[j]!=0:
                k=j
                while k<len(row) and row[k]!=0: k+=1
                seqs.append((i,j,row[j:k])); j=k
            else: j+=1
    return seqs

def transform(grid):
    out=[r[:] for r in grid]
    seqs=sequences(grid)
    from collections import defaultdict
    byval=defaultdict(list)
    for i,j,s in seqs:
        for off,v in enumerate(s): byval[v].append((i,j,off,s))
    for i,row in enumerate(grid):
        if any(i==si for si,_,_ in seqs) and any(grid[i]): continue
        for j,v in enumerate(row):
            if v!=0 and not any(si==i for si,_,_ in seqs if grid[si][j] if j<len(grid[si]) else False):
                pass
    # simpler: for every nonzero cell not part of a sequence run, extend
    seqrows={si for si,_,_ in seqs}
    for i,row in enumerate(grid):
        for j,v in enumerate(row):
            if v==0: continue
            # is it inside a run in its own row?
            runs=[(sj,s) for si,sj,s in seqs if si==i]
            inrun=any(sj<=j<sj+len(s) for sj,s in runs)
            if inrun: continue
            cands=[(sj,off,s) for si,sj,s in seqs for off,x in enumerate(s) if x==v]
            if len(cands)!=1: continue
            sj,off,s=cands[0]
            start=j-off
            for k,x in enumerate(s):
                c=start+k
                if 0<=c<len(out[0]): out[i][c]=x
    return out

